/* @lc app=leetcode id=3256 lang=kotlin */ class Solution { fun maximumValueSum(board: Array<IntArray>): Long = board.indices.flatMap { r -> board[r].indices.sortedByDescending { board[r][it] }.take(3).map { c -> Triple(board[r][c].toLong(), r, c) } }.groupBy { it.third }.values.flatMap { g -> g.sortedByDescending { it.first }.take(3) }.sortedByDescending { it.first }.let { s -> s.indices.maxOf { i -> (i + 1 until s.size).maxOfOrNull { j -> if (s[i].second == s[j].second || s[i].third == s[j].third) Long.MIN_VALUE / 4 else s[i].first + s[j].first + (s.firstOrNull { k -> k.second != s[i].second && k.second != s[j].second && k.third != s[i].third && k.third != s[j].third }?.first ?: (Long.MIN_VALUE / 4)) } ?: (Long.MIN_VALUE / 4) } } }